class Solution { fun kthSmallestPrimeFraction(arr:IntArray,k:Int):IntArray{val heap=java.util.PriorityQueue<IntArray>{a,b->(arr[a[0]].toLong()*arr[b[1]]).compareTo(arr[b[0]].toLong()*arr[a[1]])};for(j in 1 until arr.size)heap.add(intArrayOf(0,j));var remaining=k;var current=IntArray(2);while(remaining-->0){current=heap.remove();if(current[0]+1<current[1])heap.add(intArrayOf(current[0]+1,current[1]))};return intArrayOf(arr[current[0]],arr[current[1]])} }
